import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"Plan Ekranı - Coğrafi Sınır","description":"","frontmatter":{},"headers":[],"relativePath":"tr/qgc-user-guide/plan_view/plan_geofence.md","filePath":"tr/qgc-user-guide/plan_view/plan_geofence.md"}`),a={name:`tr/qgc-user-guide/plan_view/plan_geofence.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-ekranı-cografi-sınır" tabindex="-1">Plan Ekranı - Coğrafi Sınır <a class="header-anchor" href="#plan-ekranı-cografi-sınır" aria-label="Permalink to “Plan Ekranı - Coğrafi Sınır”">​</a></h1><p>Coğrafi Sınırlar, aracınızın içinde uçmasına izin verilen ya da <em>izin verilmeyen</em> sanal bölgeler oluşturmanıza olanak sağlar. Ayrıca eğer izin verilen alanın dışına çıkıldığında yaplıacak eylemi de ayarlayabilirsiniz.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p><em>QGroundControl</em> will not display the GeoFence options if they are not supported by the connected vehicle firmware.</p></div><h2 id="create-a-geofence" tabindex="-1">Create a GeoFence <a class="header-anchor" href="#create-a-geofence" aria-label="Permalink to “Create a GeoFence”">​</a></h2><p>Coğrafi Sınır Oluşturmak için:</p><ol><li><p>Plan Ekranı&#39;na gidin</p></li><li><p>Select the <strong>GeoFence</strong> layer using the <a href="./plan_view.html#layer-switcher">Layer Switcher</a> in the top-right area of the map (or expand the <strong>GeoFence</strong> section in the <a href="./plan_view.html#plan-editor-panel">Plan Editor Panel</a>)</p></li><li><p>Insert a circular or polygon region by pressing the <strong>Circular Fence</strong> or <strong>Polygon Fence</strong> button in the GeoFence section. Haritaya yeni bir bölge ve butonların altına sınırlarla ilgili yeni bir liste eklenecektir.</p></li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Butonlara birden çok kez basarak birden çok bölge oluşturabilirsiniz, böylece karmaşık coğrafi sınırlar oluşturulabilir.</p></div></div><ul><li><p>Dairesel Bölge:</p><ul><li>Merkezi noktayı kaydırarak bölgeyi haritada hareket ettirin</li><li>Resize the circle by dragging the dot on the edge of the circle (or you can change the radius value in the fence panel).</li></ul></li><li><p>Coğrafi Sınır Oluşturma</p><ul><li>İçi dolu noktaları sürükleyerek köşeleri hareket ettirin</li><li>İçi dolu noktaların arasındaki içi boş noktalara basarak yeni köşeler oluşturun.</li></ul></li></ul><ol><li>Varsayılan olarak, <em>inclusion</em> bölgeleri olarak yeni bölgeler oluşturulur (araçlar bölge içinde kalmalıdır). Sınır panelindeki <em>Inclusion</em> onay kutusunun tikini kaldırarak, exclusion bölgelerine (aracın içinde uçamayacağı) dönüştürebilirsiniz.</li></ol><p>Depending on the firmware, the GeoFence section may also show fence parameters (e.g. breach action) and a <strong>Breach Return Point</strong> that the vehicle will fly to if it breaches the fence.</p><h2 id="geofence-duzenleme-silme" tabindex="-1">GeoFence Düzenleme/Silme <a class="header-anchor" href="#geofence-duzenleme-silme" aria-label="Permalink to “GeoFence Düzenleme/Silme”">​</a></h2><p>You can select a GeoFence region to edit by selecting its <em>Edit</em> radio button in the GeoFence section. Daha sonra, önceki bölümde anlatıldığı gibi haritadaki bölgeyi düzenleyebilirsiniz.</p><p>Regions can be deleted by pressing the associated <strong>Del</strong> button.</p><h2 id="upload-a-geofence" tabindex="-1">Upload a GeoFence <a class="header-anchor" href="#upload-a-geofence" aria-label="Permalink to “Upload a GeoFence”">​</a></h2><p>The GeoFence is uploaded along with the rest of the plan using the <strong>Upload</strong> button in the <a href="./plan_view.html#file">Plan Toolbar</a>.</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};